import{_ as o,o as r,c as a,a0 as d}from"./chunks/framework.D7EjqxMK.js";const _=JSON.parse('{"title":"模块一 · 基础概念","description":"","frontmatter":{},"headers":[],"relativePath":"08-ros/01_基础概念/README.md","filePath":"08-ros/01_基础概念/README.md"}'),e={name:"08-ros/01_基础概念/README.md"};function l(s,t,i,n,h,c){return r(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="模块一-·-基础概念" tabindex="-1">模块一 · 基础概念 <a class="header-anchor" href="#模块一-·-基础概念" aria-label="Permalink to &quot;模块一 · 基础概念&quot;">​</a></h1><blockquote><p>ROS 2 知识库《模块一：基础概念》导读。本模块回答&quot;ROS 2 是什么、和 ROS 1 差在哪、怎么装、怎么构建、消息类型长什么样、生态由谁组成&quot;这六个入门必答题。</p></blockquote><h2 id="本模块包含的-6-篇文档" tabindex="-1">本模块包含的 6 篇文档 <a class="header-anchor" href="#本模块包含的-6-篇文档" aria-label="Permalink to &quot;本模块包含的 6 篇文档&quot;">​</a></h2><table tabindex="0"><thead><tr><th>序号</th><th>文档</th><th>主题</th><th>难度</th><th>一句话要点</th></tr></thead><tbody><tr><td>01</td><td><a href="./01_什么是ROS2.html">什么是 ROS 2</a></td><td>定位与心智模型</td><td>⭐⭐⭐</td><td>它是中间件+工具集，不是操作系统；DDS 通信底座 + 节点图模型</td></tr><tr><td>02</td><td><a href="./02_ROS1与ROS2对比与迁移.html">ROS 1 与 ROS 2 对比与迁移</a></td><td>差异与迁移</td><td>⭐⭐</td><td>Master 单点 → DDS 去中心化；靠 ros1_bridge 渐进迁移</td></tr><tr><td>03</td><td><a href="./03_安装与环境配置.html">安装与环境配置</a></td><td>安装与环境变量</td><td>⭐⭐⭐</td><td>发行版↔Ubuntu 绑定；source setup.bash 与 rosdep 是翻车高发区</td></tr><tr><td>04</td><td><a href="./04_工作空间与Colcon构建.html">工作空间与 Colcon 构建</a></td><td>构建工程化</td><td>⭐⭐⭐</td><td>src/ 布局 + package.xml + colcon 隔离构建</td></tr><tr><td>05</td><td><a href="./05_消息服务与类型系统.html">消息服务与类型系统</a></td><td>接口与类型</td><td>⭐⭐⭐</td><td>.msg/.srv/.action → rosidl 跨语言生成</td></tr><tr><td>06</td><td><a href="./06_ROS2生态与角色地图.html">ROS 2 生态与角色地图</a></td><td>组织与生态</td><td>⭐</td><td>OSRF/Open Robotics、ros2 仓库、index/Discourse/ROSCon、贡献流程</td></tr></tbody></table><h2 id="建议学习顺序" tabindex="-1">建议学习顺序 <a class="header-anchor" href="#建议学习顺序" aria-label="Permalink to &quot;建议学习顺序&quot;">​</a></h2><ol><li><strong>01 → 06</strong>：先建立&quot;ROS 2 是什么&quot;与&quot;生态长什么样&quot;的全局观（06 难度最低，可与 01 对读）。</li><li><strong>02</strong>：带着 ROS 1 或&quot;为什么重写&quot;的疑问，理解两大版本的架构差异。</li><li><strong>03 → 04</strong>：动手装环境、建工作区、编译第一个包——这是所有后续实践的地基。</li><li><strong>05</strong>：深入消息/服务/动作类型系统，为自定义接口做准备。</li></ol><blockquote><p>每篇末尾都有「核心面试三问」，覆盖边界条件/极端场景/失败模式，可直接用于自测与复习。</p></blockquote><h2 id="与后续模块的衔接" tabindex="-1">与后续模块的衔接 <a class="header-anchor" href="#与后续模块的衔接" aria-label="Permalink to &quot;与后续模块的衔接&quot;">​</a></h2><p>本模块是地基，后续模块在此基础上展开：</p><ul><li><strong><a href="./../02_核心模块/">模块二 · 核心模块</a></strong>：深入通信与执行机制（话题/服务/动作的实现、<a href="./../02_核心模块/05_QoS与通信机制.html">QoS 与通信机制</a>、执行器、参数/生命周期、DDS/RMW 细节）。本模块 01 里&quot;换 RMW&quot;与 05 里&quot;rosidl 流水线&quot;在此展开。</li><li><strong><a href="./../03_高级话题/">模块三 · 高级话题</a></strong>：实时性、安全（SROS2）、零拷贝、多机分布式、确定性等进阶主题。本模块 03 的环境变量（RMW/DOMAIN_ID）在此深入。</li><li><strong><a href="./../04_工程实践/">模块四 · 工程实践</a></strong>：CI、测试、发布、rosbag2、部署与容器化等落地工程。本模块 04 的 colcon/rosdep 是 CI 与发布的基础。</li><li><strong><a href="./../05_前沿趋势/">模块五 · 前沿趋势</a></strong>：新发行版、middleware 演进、标准化（如 Open-RMF/micro-ROS 等方向）。</li></ul><h2 id="使用约定" tabindex="-1">使用约定 <a class="header-anchor" href="#使用约定" aria-label="Permalink to &quot;使用约定&quot;">​</a></h2><ul><li>本模块所有「参考资料」URL 均已逐一用 web_search 验证；无法确认的一律标注 <code>⚠️ 来源待验证</code>，<strong>绝不编造</strong>。</li><li>文中源码级证据（类名/函数名/配置参数）均来自 ROS 2 官方仓库与文档，标注到具体文件/符号。</li><li>交叉引用使用相对链接，跨模块内容只做指引、不复制正文。</li></ul><hr><p><strong>📅 最后更新</strong>：2026-08-25</p>',14)])])}const R=o(e,[["render",l]]);export{_ as __pageData,R as default};
